"""Locate executed kernels in actual HLO loop bodies, not metadata alone."""
from pathlib import Path
from collections import defaultdict
import hashlib
import json
import re

directory=Path(__file__).resolve().parent
traces=json.loads((directory/'gc_kernel_profile.json').read_text())
report={}
for case,trace in traces.items():
    source=(directory/(case+'.hlo')).read_text()
    computations={}
    operations={}
    current=None
    entry=None
    for line in source.splitlines():
        if line.startswith('%') or line.startswith('ENTRY %'):
            match=re.match(r'(ENTRY )?%([^ (]+).*\{$',line)
            if match:
                current=match[2]
                computations[current]=[]
                if match[1]:entry=current
        elif current and line=='}':current=None
        elif current:
            match=re.match(r'  (?:ROOT )?%([^ ]+) = (.*)',line)
            if match:
                name,body=match.groups()
                operations[name]=(current,body)
                computations[current].append((name,body))
    depths={entry:0}
    pending=[entry]
    while pending:
        comp=pending.pop()
        for name,body in computations[comp]:
            targets=[]
            for role,target in re.findall(r'(condition|body|to_apply)=%([^, }]+)',body):
                targets.append((target,depths[comp]+(role in ('condition','body'))))
            match=re.search(r'branch_computations=\{([^}]+)\}',body)
            if match:targets += [(name.strip().removeprefix('%'),depths[comp]) for name in match[1].split(',')]
            for target,depth in targets:
                if target in computations and target not in depths:
                    depths[target]=depth
                    pending.append(target)
    groups=defaultdict(lambda:dict(calls=0,self_us=0.,kernels=[]))
    records={}
    for name,row in trace['kernels'].items():
        if name not in operations or 'hlo_op' not in row['sample_args']:
            continue
        comp,body=operations[name]
        metadata=re.search(r'op_name="([^"]+)"',body)
        op_name=metadata[1] if metadata else ''
        depth=depths.get(comp,-1)
        group='depth_'+str(depth)
        if '_compute_gamma' in op_name:group += '_geometry'
        groups[group]['calls']+=row['count']
        groups[group]['self_us']+=row['self_us']
        groups[group]['kernels'].append(name)
        records[name]=dict(computation=comp,depth=depth,metadata=op_name,
            count=row['count'],self_us=row['self_us'],expression=body)
    report[case]=dict(groups=dict(groups),kernels=records)
    print(case,json.dumps({name:{k:v for k,v in values.items() if k!='kernels'} for name,values in groups.items()}))
    for name,row in records.items():
        if '_compute_gamma' in row['metadata'] and row['count']>1:
            print(json.dumps(dict(name=name,**{k:v for k,v in row.items() if k!='expression'})))
(directory/'gc_hlo_profile.json').write_text(json.dumps(report,indent=2)+'\n')

