from pathlib import Path
from collections import Counter
import hashlib
import json
import re

directory=Path(__file__).resolve().parent
profile=json.loads((directory/'gc_hlo_profile.json').read_text())
report={}
def canonical(source):
    comps={}
    current=None
    for line in source.splitlines():
        match=re.match(r'(?:ENTRY )?%([^ (]+).*\{$',line)
        if match:current=match[1];comps[current]=[]
        elif line=='}':current=None
        elif current:
            match=re.match(r'  (?:ROOT )?%([^ ]+) = (.*)',line)
            if match:comps[current].append(match.groups())
    memo={}
    def comp_hash(name):
        if name in memo:return memo[name]
        local={var:'v'+str(i) for i,(var,_) in enumerate(comps[name])}
        parts=[]
        for var,body in comps[name]:
            body=re.sub(r', metadata=\{.*?\}', '',body)
            body=re.sub(r', frontend_attributes=\{.*?\}', '',body)
            body=re.sub(r'%([^, (){}]+)',lambda m:local[m[1]] if m[1] in local else
                'comp_'+comp_hash(m[1]) if m[1] in comps else '%unknown',body)
            parts.append(body)
        value=hashlib.sha256('\n'.join(parts).encode()).hexdigest()
        memo[name]=value
        return value
    return comp_hash
for kind in ('adaptive','fixed'):
    signatures={}
    for mode in ('before','after'):
        case='native_split_'+kind+'_'+mode
        comp_hash=canonical((directory/(case+'.hlo')).read_text())
        counters={depth:Counter() for depth in (1,2,3)}
        for name,row in profile[case]['kernels'].items():
            if row['depth'] not in counters:continue
            body=row['expression']
            call=re.search(r'calls=%([^, ]+)',body)
            if call:key=comp_hash(call[1])
            else:
                body=re.sub(r', metadata=\{.*?\}','',body)
                body=re.sub(r'%[^, (){}]+','%value',body)
                key=hashlib.sha256(body.encode()).hexdigest()
            counters[row['depth']][key]+=row['count']
        signatures[mode]=counters
    result={}
    for depth in (1,2,3):
        a,b=signatures['before'][depth],signatures['after'][depth]
        result[depth]=dict(before_calls=sum(a.values()),after_calls=sum(b.values()),
            structurally_matched_calls=sum((a&b).values()),before_distinct=len(a),after_distinct=len(b))
    report[kind]=result
    print(kind,json.dumps(result))
    for mode in ('before','after'):
        case='native_split_'+kind+'_'+mode
        top=sorted(((name,row) for name,row in profile[case]['kernels'].items() if row['depth']==1),key=lambda x:-x[1]['self_us'])[:10]
        print(case,'outer_top',json.dumps([dict(name=name,count=row['count'],self_us=row['self_us'],metadata=row['metadata']) for name,row in top]))
(directory/'gc_kernel_comparison.json').write_text(json.dumps(report,indent=2)+'\n')
